create table if not exists public.spark_campaign_participations(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.spark_campaigns(id) on delete cascade,member_id uuid not null references public.spark_members(id) on delete cascade,center_id uuid not null references public.spark_centers(id) on delete cascade,joined_at timestamptz not null default now(),source text not null default 'member',unique(campaign_id,member_id)); alter table public.spark_campaign_participations enable row level security;
create or replace function public.spark_join_campaign(p_campaign_id uuid,p_member_id uuid) returns jsonb language plpgsql security definer set search_path='public' as $$ declare v_center uuid; begin select center_id into v_center from spark_members where id=p_member_id and active=true; if v_center is null then raise exception 'MEMBER_NOT_FOUND'; end if; if not public.spark_is_staff(v_center) then raise exception 'FORBIDDEN'; end if; if not exists(select 1 from spark_campaigns where id=p_campaign_id and status='published' and starts_at<=now() and(ends_at is null or ends_at>=now())) then raise exception 'CAMPAIGN_NOT_ACTIVE'; end if; insert into spark_campaign_participations(campaign_id,member_id,center_id) values(p_campaign_id,p_member_id,v_center) on conflict(campaign_id,member_id) do nothing; return jsonb_build_object('ok',true); end $$;
create or replace function public.spark_member_campaigns(p_member_id uuid) returns table(id uuid,title text,description text,flame_code text,starts_at timestamptz,ends_at timestamptz,joined boolean) language plpgsql stable security definer set search_path='public' as $$ declare v_center uuid; begin select center_id into v_center from spark_members where id=p_member_id and active=true; if v_center is null or not public.spark_is_staff(v_center) then raise exception 'FORBIDDEN'; end if; return query select c.id,c.title,c.description,c.flame_code,c.starts_at,c.ends_at,exists(select 1 from spark_campaign_participations cp where cp.campaign_id=c.id and cp.member_id=p_member_id) from spark_campaigns c where c.status='published' and c.starts_at<=now() and(c.ends_at is null or c.ends_at>=now()) order by c.starts_at desc; end $$;
create or replace function public.spark_hq_campaign_stats() returns table(campaign_id uuid,title text,flame_code text,countries bigint,centers bigint,members bigint) language plpgsql stable security definer set search_path='public' as $$ begin if not public.spark_is_hq_admin() then raise exception 'FORBIDDEN'; end if; return query select c.id,c.title,c.flame_code,count(distinct ce.country_code),count(distinct cp.center_id),count(distinct cp.member_id) from spark_campaigns c left join spark_campaign_participations cp on cp.campaign_id=c.id left join spark_centers ce on ce.id=cp.center_id group by c.id,c.title,c.flame_code order by c.created_at desc; end $$;
create or replace function public.spark_public_campaign_stats() returns table(campaign_id uuid,title text,flame_code text,countries bigint,centers bigint,participants bigint) language sql stable security definer set search_path='public' as $$ select c.id,c.title,c.flame_code,count(distinct ce.country_code),count(distinct cp.center_id),count(distinct cp.member_id) from spark_campaigns c left join spark_campaign_participations cp on cp.campaign_id=c.id left join spark_centers ce on ce.id=cp.center_id where c.status='published' and c.starts_at<=now() and(c.ends_at is null or c.ends_at>=now()) group by c.id,c.title,c.flame_code order by c.starts_at desc; $$;
grant execute on function public.spark_join_campaign(uuid,uuid) to authenticated; grant execute on function public.spark_member_campaigns(uuid) to authenticated; grant execute on function public.spark_hq_campaign_stats() to authenticated; grant execute on function public.spark_public_campaign_stats() to anon,authenticated;